func TestCompositionExclusionsStayDecomposed(emonT *testing.T) {
	// U+0958 decomposes to U+0915 U+093C and is in Full_Composition_Exclusion,
	// so NFC leaves it decomposed -- else normalizing twice would change it.
	var src *port.Cells = port.NewCells()
	var want *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	ntLit(port.TextBlob("0958"), src)
	ntLit(port.TextBlob("0915 093C"), want)
	port.AssertEq(emonT, ntNfcIs(src, want, out, tmp), 1, "NFC(U+0958) is its decomposition")
	port.AssertEq(emonT, ntNfdIs(src, want, out), 1, "and so is NFD")
	ntLit(port.TextBlob("212B"), src)
	ntLit(port.TextBlob("00C5"), want)
	port.AssertEq(emonT, ntNfcIs(src, want, out, tmp), 1, "a singleton (angstrom sign) goes to its canonical equivalent")
}

