func TestLigaturesAndSoftHyphensAreFlags(emonT *testing.T) {
	var src *port.Cells = port.NewCells()
	var want *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	ntLit(port.TextBlob("FB00 FB01 FB02 FB03 FB04 FB05 FB06"), src)
	port.CellsDrop(out, 0)
	normalize.NzNfc(src, 0, port.CellsLen(src), out, tmp, 1)
	ntLit(port.TextBlob("66 66 66 69 66 6C 66 66 69 66 66 6C 73 74 73 74"), want)
	port.AssertEq(emonT, ntSame(out, want), 1, "FB00..FB06 expand with the ligature flag")
	port.CellsDrop(out, 0)
	normalize.NzNfc(src, 0, port.CellsLen(src), out, tmp, 0)
	port.AssertEq(emonT, ntSame(out, src), 1, "and stay as they are without it")
	ntLit(port.TextBlob("61 AD 62"), src)
	ntLit(port.TextBlob("61 62"), want)
	port.CellsDrop(out, 0)
	normalize.NzNfc(src, 0, port.CellsLen(src), out, tmp, 2)
	port.AssertEq(emonT, ntSame(out, want), 1, "U+00AD is dropped with the soft-hyphen flag")
	port.CellsDrop(out, 0)
	normalize.NzNfc(src, 0, port.CellsLen(src), out, tmp, 0)
	port.AssertEq(emonT, ntSame(out, src), 1, "and kept without it")
	ntLit(port.TextBlob("FB01 65 301"), src)
	ntLit(port.TextBlob("66 69 E9"), want)
	port.CellsDrop(out, 0)
	normalize.NzNfc(src, 0, port.CellsLen(src), out, tmp, 3)
	port.AssertEq(emonT, ntSame(out, want), 1, "flags compose with NFC: fi + e-acute")
}

